46	// GetInstanceStats returns resource usage statistics. Admin only.
47	func (s *APIV1Service) GetInstanceStats(ctx context.Context, _ *v1pb.GetInstanceStatsRequest) (*v1pb.InstanceStats, error) {
48		user, err := s.fetchCurrentUser(ctx)
49		if err != nil {
50			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
51		}
52		if user == nil {
53			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
54		}
55		if user.Role != store.RoleAdmin {
56			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
57		}
58	
59		if cached, ok := s.instanceStatsCache.get(); ok {
60			return cached, nil
61		}
62	
63		stats, err := s.computeInstanceStats(ctx)
64		if err != nil {
65			return nil, status.Errorf(codes.Internal, "failed to compute instance stats: %v", err)
66		}
67		s.instanceStatsCache.set(stats, instanceStatsCacheTTL)
68		return stats, nil
69	}
